with metrics as (select *, row_number() over (order by hire_date, id) as row_seq, percent_rank() over (partition by level order by salary desc) as salary_percent_rank, avg(salary) over (partition by level, job_title order by hire_date, id rows between 2 preceding and 1 preceding) as salary_avg_2_prior, avg(salary) over (partition by level, manager_id order by salary, id rows between 6 preceding and current row) as salary_avg_6 from employees) select id, full_name, job_title, salary, row_seq, salary_percent_rank, salary_avg_2_prior, salary_avg_6, case when full_name rlike '^(Ivy Chen|Emma Brown)$' then 'EXTENDED' when full_name rlike '^(Alice Wong|bob smith)$' then 'GROUP_B' else 'OTHER_ZONE' end as full_name_zone from metrics;
